"""Explicit BC/PPO/evaluation requests, applied by the owning trainer at a batch boundary."""
import math
from pathlib import Path
import time
import uuid
from .common import read_json
from .control import _atomic, _locked

PHASES = ('auto', 'bc', 'ppo', 'evaluate')


def request_phase(run_dir, phase, *, formats=None, force=False, reason='', hours=None):
    if phase not in PHASES: raise ValueError('unknown phase')
    if force and phase != 'ppo': raise ValueError('--force is only valid for PPO')
    if force and not reason.strip(): raise ValueError('forced PPO requires --reason')
    if hours is not None and (not math.isfinite(hours) or hours <= 0): raise ValueError('phase hours must be positive and finite')
    root=Path(run_dir)
    manifest=read_json(root/'manifest.json')
    from .features import VERSION
    if manifest.get('features',{}).get('version',VERSION)!=VERSION:
        raise ValueError('phase request requires matching data schema; do not use old checkpoints with new source')
    targets=formats or manifest['config']['formats']
    if not targets or not set(targets)<=set(manifest['config']['formats']): raise ValueError('phase formats must belong to the run')
    now=time.time();commands={}
    clock=read_json(root/'clock.json')
    inherited=clock['update_deadline' if phase=='auto' else 'deadline']
    if hours is None and inherited<=now: raise ValueError('original budget expired; provide explicit phase --hours')
    with _locked(root/'phase'):
        for fmt in targets:
            state=read_json(root/fmt/'state.json')
            if state['stage'] in ('final','finished') or state.get('failed_stage')=='final':
                raise ValueError('evaluation has started; create a new run for further training')
            if phase=='ppo' and not force and not state.get('effective'):
                raise ValueError(f'{fmt}: BC gates not passed; use --force --reason to enter PPO explicitly')
            commands[fmt]=dict(id=uuid.uuid4().hex,phase=phase,force=force,reason=reason,
                               requested_at=now,deadline=now+hours*3600 if hours is not None else None)
        for fmt,command in commands.items(): _atomic(root/'phase'/f'{fmt}.pending.json',command)
    return commands


def show_phases(run_dir):
    root=Path(run_dir);manifest=read_json(root/'manifest.json')
    result={}
    for fmt in manifest['config']['formats']:
        state=read_json(root/fmt/'state.json');path=root/'phase'/f'{fmt}.pending.json'
        result[fmt]=dict(stage=state['stage'],phase=state.get('phase','auto'),
                        pretraining_complete=state.get('effective',False),
                        history=state.get('phase_history',[]),pending=read_json(path) if path.exists() else None)
    return result


def apply_phase(runner):
    root=runner.directory.parent;path=root/'phase'/f'{runner.fmt}.pending.json'
    if not path.exists(): return
    with _locked(root/'phase'):
        if not path.exists(): return
        command=read_json(path)
        state=runner.state
        if command['id'] != state.get('phase_command_id'):
            phase=command['phase']
            if phase=='ppo' and not command['force'] and not state.get('effective'):
                raise ValueError('BC gates not passed for queued PPO phase')
            state.setdefault('phase_history',[]).append(dict(command,previous_phase=state.get('phase','auto'),
                pretraining_complete=state.get('effective',False),applied_at=time.time()))
            state.update(phase=phase,phase_deadline=command['deadline'],phase_command_id=command['id'])
            state.pop('status',None)
            if phase=='ppo' and command['force']:
                state['forced_ppo']=dict(reason=command['reason'],command_id=command['id'],version=state['version'])
            if state['stage'].endswith('_complete'):
                state['stage']='bc' if phase=='auto' else phase
            runner.save()
        path.unlink()

learning/control.py:
"""Per-format reward controls; all changes become effective at batch boundaries.

Metrics supplied to boundary are incremental, fault-free training/validation
evidence. Final holdout measurements are rejected for automatic tuning.
"""
from contextlib import contextmanager
from dataclasses import replace
import hashlib
import json
import math
import os
from pathlib import Path
import tempfile
import time
import uuid

from .rewards import RewardConfig, RANGES

FORMATS = ('duel', 'ffa4', 'team2v2')
MUTABLE = {'economy', 'control', 'explore', 'mode', 'entropy', 'bc_aux'}


def _digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(',', ':'), allow_nan=False).encode()).hexdigest()


def _read(path, default):
    return json.loads(path.read_text(encoding='utf-8')) if path.exists() else default


def _atomic(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    name = None
    try:
        with tempfile.NamedTemporaryFile(mode='w', encoding='utf-8', dir=path.parent, delete=False) as stream:
            name = stream.name
            json.dump(value, stream, sort_keys=True, allow_nan=False)
            stream.flush()
            os.fsync(stream.fileno())
        for attempt in range(6):
            try:
                os.replace(name, path)
                break
            except PermissionError:
                # Windows scanners can briefly hold a newly replaced file.
                if os.name != 'nt' or attempt == 5:
                    raise
                time.sleep(.02 * (attempt + 1))
    finally:
        if name and os.path.exists(name):
            os.unlink(name)


@contextmanager
def _locked(directory):
    directory.mkdir(parents=True, exist_ok=True)
    lock = directory / '.write-lock'
    deadline = time.monotonic() + 5
    while True:
        try:
            lock.mkdir()
            break
        except FileExistsError:
            if time.monotonic() >= deadline:
                raise RuntimeError(f'control writer lock is busy: {lock}')
            time.sleep(.025)
    try:
        yield
    finally:
        lock.rmdir()


def _events(directory):
    path = directory / 'events.jsonl'
    rows, previous = [], None
    if path.exists():
        for number, line in enumerate(path.read_text(encoding='utf-8').splitlines(), 1):
            try:
                row = json.loads(line)
                body = {k: v for k, v in row.items() if k != 'checksum'}
                if row['seq'] != number or row['previous'] != previous or row['checksum'] != _digest(body):
                    raise ValueError('event sequence/checksum mismatch')
                if row['format'] not in FORMATS:
                    raise ValueError('invalid event format')
                old, new = RewardConfig(**row['old']), RewardConfig(**row['new'])
                if new.reward_version != old.reward_version + 1:
                    raise ValueError('nonsequential reward version')
            except (ValueError, KeyError, TypeError) as exc:
                raise ValueError(f'invalid control event line {number}: {exc}') from exc
            previous = row['checksum']
            rows.append(row)
    return rows


def _changed(config, changes):
    unknown = set(changes) - MUTABLE
    if unknown:
        raise ValueError(f'unsupported control fields: {sorted(unknown)}')
    if not changes:
        raise ValueError('empty control change')
    return replace(config, **changes)


def _validate_command(config, command):
    if command['source'] not in ('manual', 'adaptive', 'scheduled') or not command['reason'] or not command.get('id'):
        raise ValueError('invalid control provenance')
    candidate = _changed(config, command['changes'])
    if command['source'] == 'adaptive':
        for name in RANGES:
            before, after = getattr(config, name), getattr(candidate, name)
            if not before * .9 - 1e-12 <= after <= before * 1.1 + 1e-12:
                raise ValueError('adaptive change exceeds 10 percent')
    return candidate


def queue_control(run_dir, format_name, changes, *, source='manual', reason='manual control', command_id=None):
    """Validate and atomically queue one complete command, never alter a live game."""
    if format_name not in FORMATS:
        raise ValueError('unknown format')
    if source not in ('manual', 'adaptive', 'scheduled') or not reason:
        raise ValueError('control source/reason required')
    directory = Path(run_dir) / 'control'
    with _locked(directory):
        events = _events(directory)
        if command_id is not None:
            existing = next((event for event in events if event.get('command_id') == command_id), None)
            if existing is not None:
                return existing
        state = _read(directory / f'{format_name}.json', {})
        config = RewardConfig(**state.get('config', {}))
        for event in events:
            if event['format'] == format_name:
                config = RewardConfig(**event['new'])
        path = directory / f'{format_name}.pending.json'
        pending = _read(path, [])
        if command_id is not None:
            existing = next((command for command in pending if command.get('id') == command_id), None)
            if existing is not None:
                return existing
        for command in pending:
            config = _changed(config, command['changes'])
        command = dict(id=command_id or uuid.uuid4().hex, changes=dict(changes), source=source, reason=reason, queued_at=time.time())
        _validate_command(config, command)
        pending.append(command)
        _atomic(path, pending)
        return command


def show_control(run_dir, format_name=None):
    directory = Path(run_dir) / 'control'
    if format_name is not None and format_name not in FORMATS:
        raise ValueError('unknown format')
    with _locked(directory):
        events = _events(directory)
        result = {}
        for fmt in (FORMATS if format_name is None else [format_name]):
            state = _read(directory / f'{fmt}.json', {})
            config = state.get('config', RewardConfig().to_dict())
            for event in events:
                if event['format'] == fmt:
                    config = event['new']
            result[fmt] = dict(config=config, pending=_read(directory / f'{fmt}.pending.json', []),
                               applied_event_seq=state.get('cursor', 0), last_error=state.get('last_error'),
                               metrics_error=state.get('metrics_error'))
        return result


class RewardController:
    def __init__(self, run_dir, format_name, state=None, config=None, schedule=None):
        if format_name not in FORMATS:
            raise ValueError('unknown format')
        self.run_dir, self.format = Path(run_dir), format_name
        self.directory = self.run_dir / 'control'
        self.schedule = schedule or []
        saved = state if state is not None else _read(self.directory / f'{format_name}.json', {})
        initial = dict(saved.get('config') or config or {})
        if schedule and config is None and not saved.get('config'):
            initial.setdefault('mode', 'scheduled')
        self.config = RewardConfig(**initial)
        self.cursor = saved.get('cursor', 0)
        self.last_check = saved.get('last_check', 0)
        self.games = saved.get('games', 0)
        self.blocks = saved.get('blocks', [])
        self.seen_blocks = set(saved.get('seen_blocks', []))
        self.windows = saved.get('windows', [])
        self.control_previous = saved.get('control_previous')
        self.last_error = saved.get('last_error')
        self.metrics_error = saved.get('metrics_error')
        self.applied_schedule = set(saved.get('applied_schedule', []))
        with _locked(self.directory):
            self._replay(_events(self.directory))
            self._save()

    def _replay(self, events):
        if self.cursor > len(events):
            raise ValueError('checkpoint control cursor is ahead of event log')
        for event in events:
            if event['seq'] <= self.cursor or event['format'] != self.format:
                continue
            if event['old'] != self.config.to_dict():
                raise ValueError('control checkpoint does not match event chain')
            if event['source'] == 'adaptive' and event['new']['control'] > event['old']['control']:
                if self.control_previous is None:
                    self.control_previous = event['old']['control']
            elif event['source'] == 'adaptive' and event['new']['control'] < event['old']['control']:
                self.control_previous = None
            self.config = RewardConfig(**event['new'])
        self.cursor = len(events)

    def freeze(self):
        """Copy this into every game/job and keep it for its entire trajectory."""
        return self.config.to_dict()

    def state_dict(self):
        return dict(config=self.freeze(), cursor=self.cursor, last_check=self.last_check,
                    games=self.games, blocks=self.blocks, seen_blocks=sorted(self.seen_blocks),
                    windows=self.windows, control_previous=self.control_previous,
                    last_error=self.last_error, metrics_error=self.metrics_error, applied_schedule=sorted(self.applied_schedule))

    def _save(self):
        _atomic(self.directory / f'{self.format}.json', self.state_dict())

    def _apply_pending(self, batch):
        path = self.directory / f'{self.format}.pending.json'
        with _locked(self.directory):
            events = _events(self.directory)
            self._replay(events)
            applied_ids = {event.get('command_id') for event in events}
            pending = [command for command in _read(path, []) if command.get('id') not in applied_ids]
            # Validate every queued command before appending any application.
            try:
                candidate = self.config
                for command in pending:
                    candidate = _validate_command(candidate, command)
            except (ValueError, TypeError, KeyError) as exc:
                self.last_error = str(exc)
                _atomic(path, [])
                self._save()
                return
            for command in pending:
                next_config = replace(_changed(self.config, command['changes']), reward_version=self.config.reward_version + 1)
                body = dict(seq=len(events) + 1, previous=events[-1]['checksum'] if events else None,
                            format=self.format, old=self.freeze(), new=next_config.to_dict(),
                            source=command['source'], reason=command['reason'], batch=batch,
                            command_id=command['id'],
                            queued_at=command['queued_at'], applied_at=time.time())
                event = dict(body, checksum=_digest(body))
                with (self.directory / 'events.jsonl').open('a', encoding='utf-8') as stream:
                    stream.write(json.dumps(event, sort_keys=True, allow_nan=False) + '\n')
                    stream.flush()
                    os.fsync(stream.fileno())
                events.append(event)
                self._replay(events)
                self.last_error = None
            if path.exists():
                _atomic(path, [])
            self._save()

    def _ingest(self, metrics):
        if metrics.get('partition') in ('holdout', 'test', 'final'):
            raise ValueError('final holdout cannot tune rewards')
        self.games += max(0, int(metrics.get('new_games', 0)) - int(metrics.get('faulted_games', 0)))
        for block in metrics.get('validation_blocks', []):
            key = str(block['id'])
            if key in self.seen_blocks or not block.get('complete') or block.get('faults'):
                continue
            if block.get('partition') in ('holdout', 'test', 'final'):
                raise ValueError('final holdout cannot tune rewards')
            self.seen_blocks.add(key)
            self.blocks.append(block)

    @staticmethod
    def _window(blocks):
        # Match each map/faction to its own Astra reference, then give strata
        # equal weight. Sampling a large easy map cannot dominate this panel.
        strata = {}
        for block in blocks:
            for row in block.get('strata', []):
                key = (row['map'], row['faction'])
                strata.setdefault(key, []).append(row)
        if not strata:
            return None
        low_explore, met_explore, low_control, safe = [], [], [], []
        for rows in strata.values():
            def average(name):
                values = [float(row[name]) for row in rows]
                if not all(math.isfinite(v) for v in values):
                    raise ValueError('nonfinite controller metric')
                return sum(values) / len(values)
            ratios = [average(f'coverage{turn}') / max(1e-9, average(f'astra_coverage{turn}')) for turn in (5, 10)]
            low_explore.append(all(ratio < .9 for ratio in ratios))
            met_explore.append(all(ratio >= .9 for ratio in ratios))
            low_control.append(average('control') < .8 * average('astra_control'))
            safe.append(average('leader_survival') >= average('astra_leader_survival') and average('loss') <= average('astra_loss'))
        def score(name):
            values = [float(block[name]) for block in blocks if block.get(name) is not None]
            if not all(math.isfinite(v) for v in values):
                raise ValueError('nonfinite score')
            return sum(values) / len(values) if values else None
        return dict(low_explore=all(low_explore), met_explore=all(met_explore),
                    low_control=all(low_control), safe=all(safe),
                    fixed_score=score('fixed_score'), native_score=score('native_score'),
                    control=sum(float(row['control']) for rows in strata.values() for row in rows) / sum(map(len, strata.values())),
                    strata=sorted('|'.join(key) for key in strata))

    def _decision(self, metrics):
        while len(self.blocks) >= 12 and len(self.windows) < 3:
            blocks, self.blocks = self.blocks[:12], self.blocks[12:]
            window = self._window(blocks)
            if window is None:
                return {}, 'missing Astra calibration'
            self.windows.append(window)
            self.windows = self.windows[-3:]
        if len(self.windows) < 2:
            return {}, 'insufficient rotation blocks'
        window = self.windows[-1]
        if self.windows[-2]['strata'] != window['strata']:
            return {}, 'need two comparable windows'
        previous = self.windows[-2]
        changes, reasons = {}, []
        if all(w['low_explore'] and w['safe'] for w in (previous, window)):
            changes['explore'] = self.config.explore * 1.1
            reasons.append('coverage below 90% Astra without survival/loss regression')
        elif len(self.windows) >= 3 and all(w['met_explore'] for w in self.windows):
            changes['explore'] = self.config.explore * .9
            reasons.append('coverage maintained across three windows')
        if all(w['low_control'] for w in (previous, window)):
            changes['control'] = self.config.control * 1.1
            reasons.append('control below 80% Astra in two windows')
        # Two successive score declines need three windows (each >=12 blocks).
        if self.control_previous is not None and len(self.windows) == 3:
            for name in ('fixed_score', 'native_score'):
                values = [w[name] for w in self.windows]
                controls = [w['control'] for w in self.windows]
                if all(v is not None for v in values) and values[2] < values[1] < values[0] and controls[2] > controls[1] > controls[0]:
                    changes['control'] = max(self.config.control * .9, self.control_previous)
                    reasons.append(f'rollback control after two {name} declines')
                    break
        shaping, terminal = metrics.get('shaping_rms'), metrics.get('terminal_rms')
        if shaping is not None and terminal is not None and math.isfinite(shaping) and math.isfinite(terminal) and shaping > 2 * max(terminal, 1e-9):
            changes['economy'] = self.config.economy * .9
            reasons.append('shaping RMS exceeds twice terminal RMS')
        for name in list(changes):
            lo, hi = RANGES[name]
            current = getattr(self.config, name)
            changes[name] = min(hi, current * 1.1, max(lo, current * .9, changes[name]))
            if abs(changes[name] - getattr(self.config, name)) < 1e-12:
                del changes[name]
        return changes, '; '.join(reasons)

    def boundary(self, batch, metrics=None):
        """Call after the previous collection/update finishes, before next jobs.

        `new_games` is an incremental count. validation_blocks have globally
        unique IDs, complete rotation flags and per-map/faction `strata` rows.
        See REWARD_TEST_SCOPE.md for the evidence contract and future checks.
        """
        if type(batch) is not int or batch < 0:
            raise ValueError('invalid batch')
        self._apply_pending(batch)
        metrics = metrics or {}
        self._ingest(metrics)
        if metrics.get('status') == 'error':
            self.metrics_error = metrics.get('error', 'control metrics unavailable')
        elif 'validation_blocks' in metrics:
            self.metrics_error = None
        if self.config.mode == 'scheduled':
            for index, item in enumerate(self.schedule):
                if index not in self.applied_schedule and batch >= item['batch']:
                    command_id = _digest(dict(format=self.format, schedule_index=index, item=item))
                    queue_control(self.run_dir, self.format, item['changes'], source='scheduled', reason=f'schedule {index}', command_id=command_id)
                    self.applied_schedule.add(index)
        elif self.config.mode == 'adaptive' and self.metrics_error is None and batch - self.last_check >= 50 and self.games >= 64:
            self.last_check = batch
            changes, reason = self._decision(metrics)
            if changes:
                command_id = _digest(dict(format=self.format, batch=batch, changes=changes, source='adaptive'))
                queue_control(self.run_dir, self.format, changes, source='adaptive', reason=reason, command_id=command_id)
            self.games = 0
        self._apply_pending(batch)
        return self.freeze()

learning/coordinator.py:
"""Isolated trainer processes; one shared, fair pool of native game workers."""
from collections import deque
from concurrent.futures import ProcessPoolExecutor
from multiprocessing import get_context
from pathlib import Path
from queue import Empty
import json
import time
import traceback
from .common import ROOT, read_json, write_json
from .formats import FORMATS
from .manifest import output_path, freeze, verify_frozen
from .experiment import FormatExperiment, default_config, validate_config, run_lock
from .export import export_checkpoints
from .sample import play_job


class FairScheduler:
    def __init__(self,formats):
        self.order=deque(formats);self.pending={f:deque() for f in formats}

    def add(self,fmt,jobs): self.pending[fmt].extend(jobs)

    def pop(self):
        for _ in range(len(self.order)):
            fmt=self.order[0];self.order.rotate(-1)
            if self.pending[fmt]: return fmt,self.pending[fmt].popleft()
        return None


def limit_memory(gigabytes):
    """Cap trainer address space so a runaway read fails inside the trainer.

    The kernel then raises MemoryError, the trainer records its traceback and the
    coordinator reports a partial failure instead of an OOM kill of the run.
    """
    if not gigabytes: return None
    try:
        import resource
        budget=int(float(gigabytes)*1024**3)
        soft,hard=resource.getrlimit(resource.RLIMIT_AS)
        if hard!=resource.RLIM_INFINITY: budget=min(budget,hard)
        resource.setrlimit(resource.RLIMIT_AS,(budget,budget))
        return budget
    except (ImportError,ValueError,OSError):
        return None


def trainer_main(directory,fmt,manifest,clock,requests,replies,resume):
    limit_memory(manifest.get('config',{}).get('trainer_memory_gb'))
    def collect(jobs,log):
        requests.put((fmt,jobs,str(log)))
        reply=replies.get()
        if reply.get('error'): raise RuntimeError(reply['error'])
        return reply['results']
    try: FormatExperiment(directory,fmt,manifest,clock,collect,resume).run()
    except BaseException:
        Path(directory).mkdir(parents=True,exist_ok=True)
        Path(directory,'trainer_error.log').write_text(traceback.format_exc(),encoding='utf-8')
        raise


def broker(processes,requests,replies,workers,directory,play=play_job):
    """At most workers submitted games across all trainers, round robin by format."""
    if not 1<=workers<=16: raise ValueError('workers must be in [1,16]')
    scheduler=FairScheduler(processes);batches={};inflight={};peak=0
    events=Path(directory)/'scheduler.jsonl'
    def emit(row):
        with events.open('a',encoding='utf-8') as f: f.write(json.dumps(dict(time=time.time(),**row))+'\n')
    def complete(fmt,job,result):
        batch=batches[fmt];batch['results'].append(result)
        log=Path(batch['log']);log.parent.mkdir(parents=True,exist_ok=True)
        if log.exists():
            with log.open('r+b') as f:
                raw=f.read()
                if raw and not raw.endswith(b'\n'): f.truncate(raw.rfind(b'\n')+1)
        with log.open('a',encoding='utf-8') as f: f.write(json.dumps(result,ensure_ascii=False)+'\n')
        batch['remaining']-=1
        if batch['remaining']==0:
            replies[fmt].put(dict(results=batch['results']));del batches[fmt]
    exits=Path(directory)/'trainer_exit.log';reported=set()
    with ProcessPoolExecutor(max_workers=workers,mp_context=get_context('spawn')) as pool:
        while any(p.is_alive() for p in processes.values()) or inflight or batches:
            try:
                while True:
                    fmt,jobs,log=requests.get_nowait()
                    if fmt in batches: raise RuntimeError('overlapping trainer batches')
                    if not jobs: replies[fmt].put(dict(results=[]));continue
                    batches[fmt]=dict(remaining=len(jobs),results=[],log=log);scheduler.add(fmt,jobs)
            except Empty: pass
            for fmt,p in processes.items():
                if not p.is_alive() and p.exitcode not in (None,0) and fmt not in reported:
                    reported.add(fmt)
                    with exits.open('a',encoding='utf-8') as f:
                        f.write(json.dumps(dict(time=time.time(),format=fmt,exit_code=p.exitcode))+ '\n')
                if not p.is_alive() and fmt in batches:
                    while scheduler.pending[fmt]:
                        job=scheduler.pending[fmt].popleft();complete(fmt,job,dict(id=job['id'],status='trainer_failed'))
            while len(inflight)<workers:
                item=scheduler.pop()
                if item is None: break
                fmt,job=item
                if time.time()>=job['deadline']:
                    complete(fmt,job,dict(id=job['id'],status='budget_interrupted'));continue
                inflight[pool.submit(play,job)]=(fmt,job)
                peak=max(peak,len(inflight));emit(dict(event='start',format=fmt,id=job['id'],active=len(inflight)))
            done=[f for f in inflight if f.done()]
            for future in done:
                fmt,job=inflight.pop(future)
                try: result=future.result()
                except Exception as exc: result=dict(id=job['id'],status='infrastructure_error',error=repr(exc))
                complete(fmt,job,result);emit(dict(event='finish',format=fmt,id=job['id'],active=len(inflight)))
            if not done: time.sleep(.02)
    return dict(workers=workers,peak_native_games=peak,exit_codes={f:p.exitcode for f,p in processes.items()})


class Experiment:
    def __init__(self,directory,config=None,opponents=None,wesnoth=None,resume=False):
        self.directory=output_path(directory);self.resume=resume
        if resume:
            self.manifest=read_json(self.directory/'manifest.json')
            self.config=self.manifest['config']
            from .features import select_rules
            select_rules(self.config.get('rules_dir',ROOT/'rules/1.18.8'))
            verify_frozen(self.manifest)
            self.clock=read_json(self.directory/'clock.json')
        else:
            requested=dict(config or {})
            self.config=default_config(requested.get('device','cuda'),engine=requested.get('engine'))|requested;validate_config(self.config)
            from .features import select_rules
            from .rules_catalog import load, resolve_dir
            self.config['rules_dir']=str(resolve_dir(self.config.get('rules_dir')))
            select_rules(self.config['rules_dir'])
            load(self.config['rules_dir'])
            if self.config['engine']=='lite' and not self.config['allow_approximate']:
                raise ValueError('training rules contain documented approximations; enable allow_approximate for lite')
            self.directory.mkdir(parents=True,exist_ok=False)
            self.manifest,_=freeze(self.directory,opponents or ROOT/'opponents',wesnoth,self.config)
            started=time.time();duration=self.config['hours']*3600
            self.clock=dict(started=started,update_deadline=started+duration*10/12,deadline=started+duration)
            write_json(self.directory/'clock.json',self.clock)

    def run(self):
        with run_lock(self.directory):
            ctx=get_context('spawn');requests=ctx.Queue();processes={};replies={}
            for fmt in self.config['formats']:
                replies[fmt]=ctx.Queue()
                p=ctx.Process(target=trainer_main,args=(str(self.directory/fmt),fmt,self.manifest,self.clock,requests,replies[fmt],self.resume),name='trainer-'+fmt)
                processes[fmt]=p;p.start()
            try: scheduling=broker(processes,requests,replies,self.config['workers'],self.directory)
            except KeyboardInterrupt:
                for p in processes.values():
                    if p.is_alive(): p.terminate()
                raise
            finally:
                for p in processes.values(): p.join()
                requests.close()
                for q in replies.values(): q.close()
            reports={}
            for fmt in self.config['formats']:
                path=self.directory/fmt/'report/summary.json'
                reports[fmt]=read_json(path) if path.exists() else dict(status='trainer_failed',exit_code=processes[fmt].exitcode)
            successful=all(processes[f].exitcode==0 and not reports[f].get('error') for f in processes)
            status=('stage_complete' if any(r.get('status')=='stage_complete' for r in reports.values()) else 'finished') if successful else 'partial_failure'
            summary=dict(status=status,formats=reports,clock=self.clock,scheduler=scheduling)
            checkpoints={f:self.directory/f/'selected.pt' for f in FORMATS}
            if all(p.exists() for p in checkpoints.values()) and not (self.directory/'delivery/NeuralArena.zip').exists():
                # Packaging is a separate, explicit command after the continuous-memory parity audit.
                summary['delivery']='pending_explicit_export_with_sequence_audit'
            write_json(self.directory/'summary.json',summary)
            return summary

learning/lite_host.py:
"""Persistent direct Rust/Lua collection using the shared native Lua modules.

Only explicit game specs can be collected: this layer never fabricates standard
era factions, leader definitions or frozen maps from incomplete local data.
"""
from __future__ import annotations

import json
import math
import time
import zipfile
from pathlib import Path

from .adapters import LiteAdapter, ROOT


def _lua(value):
    if value is None:
        return 'nil'
    if value is True:
        return 'true'
    if value is False:
        return 'false'
    if isinstance(value, (int, float)):
        if not math.isfinite(value):
            raise ValueError('nonfinite Lua schema value')
        return repr(value)
    if isinstance(value, str):
        # JSON is not Lua string escaping (notably \u and surrogate pairs).
        return '"' + ''.join('\\' + c if c in '\\"' else '\\%03d' % ord(c)
                             if ord(c) < 32 else c for c in value) + '"'
    if isinstance(value, dict):
        return '{' + ','.join('[' + _lua(k) + ']=' + _lua(v) for k, v in value.items()) + '}'
    return '{' + ','.join(_lua(v) for v in value) + '}'


def host_modules(teacher_path=None):
    from .features import schema
    modules = {name: (ROOT / 'lua' / name).read_text(encoding='utf-8')
               for name in ('observation.lua', 'candidates.lua', 'spatial.lua', 'routing.lua', 'rewards.lua')}
    modules['features.lua'] = 'return ' + _lua(schema())
    with zipfile.ZipFile(teacher_path or ROOT / 'opponents/gpt6astra.zip') as archive:
        for name in ('duel.lua', 'four.lua', 'bot.lua'):
            modules['astra/' + name] = archive.read('gpt6astra/lua/' + name).decode('utf-8')
    return modules


class LiteHost:
    def __init__(self, game_spec, rules_dir=None, *, require_accepted=True, teacher_path=None):
        self.adapter = LiteAdapter(game_spec, rules_dir, require_accepted=require_accepted)
        from .features import schema
        if schema()['rules_sha256'] != self.adapter.rules_sha256:
            raise ValueError('shared feature vocabulary is frozen from another rules catalog')
        self.modules = host_modules(teacher_path)
        self.adapter.configure_host(self.modules)

    def reset(self, game_spec):
        self.adapter.reset(game_spec)

    def decision(self, side, *, teacher=False, budget_ms=500, generate_candidates=True):
        return self.adapter.decision(side, teacher=teacher, budget_ms=budget_ms,
                                     generate_candidates=generate_candidates)

    def execute(self, action):
        return self.adapter.execute_candidate(action)

    def snapshot(self):
        return self.adapter.snapshot()

    def restore(self, snapshot):
        self.adapter.restore(snapshot)


def teacher_candidate(plan):
    """Translate Astra's original intent without adding it to student candidates."""
    kind = plan['kind']
    if kind == 'combat':
        if plan['x'] == plan['tx'] and plan['y'] == plan['ty']:
            return dict(kind='attack', x=plan['x'], y=plan['y'], tx=plan['ex'], ty=plan['ey'], weapon=plan['weapon'])
        return dict(kind='move_attack', x=plan['x'], y=plan['y'], tx=plan['tx'], ty=plan['ty'],
                    ex=plan['ex'], ey=plan['ey'], weapon=plan['weapon'])
    if kind == 'move':
        return dict(kind='move', x=plan['x'], y=plan['y'], tx=plan['tx'], ty=plan['ty'], full=True)
    if kind in ('recruit', 'end_turn'):
        return {k: v for k, v in plan.items() if k in ('kind', 'type', 'x', 'y')}
    raise ValueError(f'unsupported Astra intent {kind}')


def _matching(candidates, action):
    fields = {'end_turn': (), 'move': ('x', 'y', 'tx', 'ty', 'full'),
              'attack': ('x', 'y', 'tx', 'ty', 'weapon'),
              'move_attack': ('x', 'y', 'tx', 'ty', 'ex', 'ey', 'weapon'),
              'recruit': ('type', 'x', 'y')}
    for i, candidate in enumerate(candidates):
        if candidate['kind'] == action['kind'] and all(candidate.get(k) == action.get(k) for k in fields[action['kind']]):
            return i
    return -1


def play_lite_job(job):
    """Play one accepted-lite Astra or explicit policy job; never fallback native.

    policy callbacks receive only the common decision DTO. Official baseline is
    unsupported in lite. No hidden true state enters Astra or policy callbacks.
    """
    from .features import schema
    from .data import write_shard
    from .rewards import RewardConfig
    from .lite_policy import FrozenPolicies,game_spec,is_astra
    from .reward_metrics import summarize_game
    job_id = job['id']
    try:
        if time.time() >= job.get('deadline', float('inf')):
            return dict(id=job_id, status='budget_interrupted', engine='lite')
        if 'game_spec' not in job:
            from .rules_catalog import resolve_dir
            rules_dir=resolve_dir(job.get('rules_dir'))
            rules=json.loads((rules_dir/'rules.json').read_text(encoding='utf-8'))
            job=dict(job,game_spec=game_spec(job,rules))
        bots = job.get('bots', [])
        policy = job.get('policy')
        if any(bot=='baseline' for bot in bots): raise ValueError('official baseline is native-only')
        policies=FrozenPolicies(job) if policy is None else None
        teacher_paths = list(bots) + [job.get('learning', {}).get('dagger_teacher')]
        teacher_path = next((Path(p) for p in teacher_paths
                             if isinstance(p, (str, Path)) and is_astra(p)
                             and Path(p).suffix == '.zip'), None)
        host = LiteHost(job['game_spec'], job.get('rules_dir'),
                        require_accepted=job.get('require_accepted', True), teacher_path=teacher_path)
        records, timings, behavior, bootstraps, metric_snapshots = [], [], [], {}, []
        config = job.get('reward_config') or RewardConfig().to_dict()
        config = RewardConfig(**config).to_dict()
        rank_points, defeated = {}, set()
        decision_count = 0
        current = 1
        learning=job.get('learning',{}).get('sides',{})
        learner_sides=set(map(int,learning)) if learning else set(job.get('learner_sides',[]))
        def metric_snapshot(side,event):
            row=host.decision(side,teacher=False,generate_candidates=False)
            snapshot={k:row[k] for k in ('side','turn','global','spatial','reward_raw')}
            snapshot.update(metric_event=event,source='astra' if is_astra(bots[side-1]) else 'policy',
                            teacher='gpt6astra' if is_astra(bots[side-1]) else False,
                            rules_version=host.adapter.catalog['rules_version'])
            metric_snapshots.append(snapshot)
        for side in sorted(learner_sides):
            metric_snapshot(side,'initial')
        query_count={};side_decisions={};dagger=[];query_total=0
        while True:
            view = host.adapter.observe(current)
            if view['finished']:
                break
            current = view['current_side']
            if time.time() >= job.get('deadline', float('inf')):
                return dict(id=job_id, status='budget_interrupted', engine='lite')
            if decision_count >= job.get('max_decisions', 100000):
                raise RuntimeError('lite decision budget exhausted; no progress/teacher loop must be diagnosed')
            decision_count += 1
            teacher=is_astra(bots[current-1]) if policies else False
            side_decisions[current]=side_decisions.get(current,0)+1
            query=not teacher and current in learner_sides and job.get('learning',{}).get('dagger_teacher') and side_decisions[current]%4==0 and query_total<32
            # Unrecorded Astra seats need their plan, not student candidates.
            # Policy seats (including DAgger queries) always need the full set.
            decision = host.decision(current, teacher=teacher or bool(query),
                                     generate_candidates=not teacher or current in learner_sides)
            training=learning.get(str(current),{})
            decision.update(schema=schema()['version'], format=job.get('format', job.get('meta', {}).get('format')),
                            source='astra' if teacher else 'policy', engine_id='lite',
                            rules_version=host.adapter.catalog['rules_version'],
                            rules_sha256=host.adapter.rules_sha256, rng_version='xoshiro256++-1',
                            version=training.get('version','teacher-frozen' if teacher else 'v5-validation'),decision=decision_count,
                            architecture_id='relational_v5', candidate_version=f"schema{schema()['version']}-"+decision['timing'].get('budget','fixed-20000-v1'),
                            engine='lite', engine_version='lite-0.1',
                            teacher_impl='astra_lite' if teacher else None,
                            teammate_context=job.get('meta',{}).get('context','astra_partner' if job.get('teams') else 'solo'),
                            data_pool=job.get('data_pool', 'original'),
                            reward_config=config, reward_version=config['reward_version'],
                            map=job.get('meta',{}).get('map'),map_sha256=job.get('meta',{}).get('map_sha256'),map_partition=job.get('meta',{}).get('map_partition'),
                            reward_formula_id=config['reward_formula_id'], game_family=job.get('game_family', job_id))
            teacher_plan=decision.pop('teacher_action',None)
            if teacher:
                action = teacher_candidate(teacher_plan)
                choice = _matching(decision['candidates'], action)
                decision.update(choice=choice, log_probability=0., value=0., teacher='gpt6astra',
                                actual=action, intent=action, representable=True)
            else:
                # Judge scalars supervise value/reward only. The actor receives
                # exactly the public common Lua observation and candidates.
                actor_input = {k: v for k, v in decision.items() if k not in ('reward_raw', 'reward_after', 'teacher_action')}
                selected = policies.choose(actor_input,current) if policies else policy(actor_input)
                choice = int(selected['choice'])
                if not 0 <= choice < len(decision['candidates']):
                    raise ValueError('policy returned an invalid candidate index')
                action = decision['candidates'][choice]
                decision.update(choice=choice, log_probability=float(selected['log_probability']),
                                value=float(selected['value']), actual=action, intent=action)
            outcome = host.execute(action)
            decision['outcome'] = outcome['events']
            decision['diagnostics'] = outcome['diagnostics']
            decision['reward_after'] = outcome['reward_after']
            decision['committed']=outcome['committed']
            if outcome.get('memory_write'): decision['memory_write']=dict(outcome['memory_write'],turn=decision['turn'])
            if policies and not teacher: policies.commit(current,decision,outcome)
            behavior.append(outcome['diagnostics']);timings.append(decision['timing']['ms'])
            if current in learner_sides:
                records.append(decision)
                if not teacher and job.get('learning',{}).get('dagger_teacher'):
                    label=dict(decision,source='astra',teacher='gpt6astra',teacher_impl='astra_lite',choice=-1,value_valid=False,data_pool='dagger')
                    if query:
                        query_count[current]=query_count.get(current,0)+1;query_total+=1
                        wanted=teacher_candidate(teacher_plan);label.update(actual=wanted,intent=wanted,choice=_matching(decision['candidates'],wanted),query_only=True)
                    dagger.append(label)
            view = outcome['view'];current = view['current_side']
            newly = {s['id'] for s in view['sides'] if s['eliminated']} - defeated
            if newly:
                points = len(defeated) + (len(newly)-1)/2
                rank_points.update({str(s): points for s in newly});defeated.update(newly)
                for side in sorted(newly & learner_sides):
                    metric_snapshot(side,'eliminated')
            if view['finished']:
                break
        if view['truncated'] and any(not is_astra(bots[side-1]) for side in learner_sides):
            # Never replace missing truncation values with zero or a teacher score.
            bootstrap_policy = job.get('bootstrap_policy')
            if bootstrap_policy is None and policies is None:
                raise RuntimeError('truncated policy game requires a frozen bootstrap_policy callback')
            for side in learner_sides:
                if is_astra(bots[side-1]): continue
                decision = host.decision(side, teacher=False)
                actor_input = {k: v for k, v in decision.items() if k not in ('reward_raw', 'reward_after', 'teacher_action')}
                bootstraps[str(side)] = dict(side=side, value=policies.choose(actor_input,side,bootstrap=True) if policies else float(bootstrap_policy(actor_input)),
                                             potential=decision['potential'], reward_raw=decision['reward_raw'], turn=decision['turn'],
                                             version=job.get('learning', {}).get('version', 'v5-validation'))
        survivors = [s['id'] for s in view['sides'] if not s['eliminated']]
        if not view['truncated']:
            for side in sorted(learner_sides-set(defeated)):
                metric_snapshot(side,'terminal')
        points = len(defeated) + (len(survivors)-1)/2
        rank_points.update({str(s): points for s in survivors})
        teams = [s['team'] for s in job['game_spec']['sides']]
        winning_sides = [s['id'] for s in view['sides'] if s['team'] == view['winner']]
        result = dict(engine_id='lite-0.1', winner=winning_sides[0] if len(winning_sides)==1 else 0,
                      winning_team=view['winner'] or 0, truncated=view['truncated'],
                      reason='turn_limit' if view['truncated'] else 'victory', survivors=survivors,
                      bots=bots or ['gpt6astra']*len(teams), factions=job.get('factions') or [None]*len(teams), teams=teams if len(set(teams))<len(teams) else None,
                      turns=view['turn'], faults=[], rank_points=rank_points, approximate=True)
        written = write_shard(job['shard'], job_id, records, result, bootstraps) if job.get('shard') else None
        if dagger and job.get('shard'):
            path=Path(job['shard']);write_shard(path.with_name(path.name.replace('.jsonl.gz','.dagger.jsonl.gz')),job_id,dagger,result,bootstraps)
        coverage = {'total': len(records), 'matched': sum(r['choice'] >= 0 for r in records),
                    'kinds': {kind: {'total': sum(r['actual']['kind'] == kind for r in records),
                                     'matched': sum(r['actual']['kind'] == kind and r['choice'] >= 0 for r in records)}
                              for kind in ('recruit', 'move', 'attack', 'move_attack', 'end_turn')}}
        for key in ('total','matched'): coverage['kinds']['attack'][key]+=coverage['kinds']['move_attack'][key]
        return dict(id=job_id, status='complete', engine='lite', result=result, coverage=coverage,
                    reward_diagnostics=summarize_game(records,result,job,snapshots=metric_snapshots),
                    training_eligible=written is None or bool(written['written']), training_shard=written,
                    behavior=behavior, timings=timings, native_timings=[], meta=job.get('meta', {}),
                    truncated=sum(r['timing'].get('truncated', False) for r in records))
    except (RuntimeError, ValueError, ImportError, OSError, KeyError) as exc:
        return dict(id=job_id, status='infrastructure_error', engine='lite', error=str(exc))

